/**
 * The machines of the basic controls as text, by control kind, so they
 * load without a file system or a bundler. They are byte-equal to the
 * `.lino` files next to this module (generated by
 * experiments/gen-control-machines.mjs; tests/controls/machines.test.js
 * checks that they stay in sync).
 */

/** Machine text by control kind. */
export const CONTROL_MACHINES = Object.freeze({
  button: `(button-machine: machine
  (initial idle)
  (context (disabled false))
  (state idle
    (on down (target pressed) (when not-disabled)))
  (state pressed
    (on up (target idle))
    (on leave (target idle)))
  (part root
    (attr data-state (state))
    (on pointerdown down)
    (on pointerup up)
    (on pointerleave leave)
    (on pointercancel leave)))
`,
  checkbox: `(checkbox-machine: machine
  (initial ready)
  (context (checked false) (disabled false) (invalid false))
  (state ready
    (on toggle (do (toggle checked)) (when not-disabled)))
  (part input
    (attr aria-invalid (context invalid))
    (attr data-state (context checked))
    (on change toggle)))
`,
  'color-field': `(color-field-machine: machine
  (initial idle)
  (context (disabled false) (invalid false))
  (state idle
    (on commit (do read-value) (when not-disabled))
    (on pick (do read-picker) (when not-disabled))
    (on revert (do restore-value) (when not-disabled)))
  (part input
    (attr aria-invalid (context invalid))
    (on change commit)
    (key Escape revert))
  (part indicator
    (on change pick)))
`,
  combobox: `(combobox-machine: machine
  (initial closed)
  (context (disabled false) (readonly false) (invalid false))
  (action close-list (activate none))
  (state closed
    (on type (target open) (do filter) (when editable))
    (on next (target open) (do (filter all) (activate first)) (when editable))
    (on previous (target open) (do (filter all) (activate last)) (when editable))
    (on open (target open) (do (filter all)) (when editable))
    (on commit (do read-value))
    (on close (do clear-value) (when editable)))
  (state open
    (on type (do filter))
    (on next (do (activate next)))
    (on previous (do (activate previous)))
    (on commit (target closed) (do select-active close-list))
    (on pick (target closed) (do select-picked close-list))
    (on close (target closed) (do close-list))
    (on blur (target closed) (do read-value close-list)))
  (part input
    (attr role combobox)
    (attr aria-autocomplete list)
    (attr aria-expanded (in open))
    (attr aria-activedescendant (context active))
    (attr aria-invalid (context invalid))
    (attr data-state (state))
    (key ArrowDown next)
    (key ArrowUp previous)
    (key Alt+ArrowDown open)
    (key Enter commit)
    (key Escape close)
    (on input type)
    (on focusout blur))
  (part listbox
    (attr role listbox)
    (attr hidden (present (in closed)))
    (attr data-state (state))
    (on click pick)))
`,
  'icon-button': `(icon-button-machine: machine
  (initial idle)
  (context (disabled false))
  (state idle
    (on down (target pressed) (when not-disabled)))
  (state pressed
    (on up (target idle))
    (on leave (target idle)))
  (part root
    (attr data-state (state))
    (on pointerdown down)
    (on pointerup up)
    (on pointerleave leave)
    (on pointercancel leave)))
`,
  'number-field': `(number-field-machine: machine
  (initial ready)
  (context (disabled false) (readonly false) (invalid false))
  (state ready
    (on commit (do read-value))
    (on revert (do restore-value) (when editable))
    (on arrow-up (do (numeric-key ArrowUp)) (when editable))
    (on arrow-down (do (numeric-key ArrowDown)) (when editable))
    (on shift-arrow-up (do (numeric-key ArrowUp shift)) (when editable))
    (on shift-arrow-down (do (numeric-key ArrowDown shift)) (when editable))
    (on page-up (do (numeric-key PageUp)) (when editable))
    (on page-down (do (numeric-key PageDown)) (when editable))
    (on home (do (numeric-key Home)) (when editable))
    (on end (do (numeric-key End)) (when editable)))
  (part input
    (attr role spinbutton)
    (attr aria-valuenow (context value))
    (attr aria-valuemin (context min))
    (attr aria-valuemax (context max))
    (attr aria-invalid (context invalid))
    (on change commit)
    (key ArrowUp arrow-up)
    (key ArrowDown arrow-down)
    (key Shift+ArrowUp shift-arrow-up)
    (key Shift+ArrowDown shift-arrow-down)
    (key PageUp page-up)
    (key PageDown page-down)
    (key Home home)
    (key End end)
    (key Escape revert)))
`,
  'radio-group': `(radio-group-machine: machine
  (initial ready)
  (context (disabled false) (invalid false))
  (state ready
    (on select (do choose-radio) (when not-disabled)))
  (part root
    (attr role radiogroup)
    (attr aria-disabled (context disabled))
    (attr aria-invalid (context invalid))
    (key Space select)
    (on press select)))
`,
  select: `(select-machine: machine
  (initial closed)
  (context (disabled false) (invalid false))
  (action open-list (activate selected))
  (action close-list (activate none))
  (state closed
    (on toggle (target open) (do open-list) (when not-disabled))
    (on open (target open) (do open-list) (when not-disabled))
    (on next (target open) (do open-list) (when not-disabled))
    (on previous (target open) (do open-list) (when not-disabled))
    (on first (target open) (do open-list (activate first)) (when not-disabled))
    (on last (target open) (do open-list (activate last)) (when not-disabled))
    (on commit (target open) (do open-list) (when not-disabled))
    (on typeahead (target open) (do open-list typeahead) (when not-disabled)))
  (state open
    (on toggle (target closed) (do close-list))
    (on close (target closed) (do close-list))
    (on blur (target closed) (do close-list))
    (on next (do (activate next)))
    (on previous (do (activate previous)))
    (on first (do (activate first)))
    (on last (do (activate last)))
    (on typeahead (do typeahead))
    (on commit (target closed) (do select-active close-list))
    (on pick (target closed) (do select-picked close-list)))
  (part input
    (attr role combobox)
    (attr aria-haspopup listbox)
    (attr aria-expanded (in open))
    (attr aria-activedescendant (context active))
    (attr aria-invalid (context invalid))
    (attr data-state (state))
    (key ArrowDown next)
    (key ArrowUp previous)
    (key Alt+ArrowDown open)
    (key Alt+ArrowUp commit)
    (key Home first)
    (key End last)
    (key PageDown last)
    (key PageUp first)
    (key Enter commit)
    (key Space commit)
    (key Escape close)
    (on press toggle)
    (on focusout blur))
  (part listbox
    (attr role listbox)
    (attr hidden (present (in closed)))
    (attr data-state (state))
    (on click pick)))
`,
  slider: `(slider-machine: machine
  (initial idle)
  (context (disabled false) (orientation horizontal))
  (state idle
    (on grab (target dragging) (do move-to-pointer) (when not-disabled))
    (on arrow-up (do (numeric-key ArrowUp)) (when not-disabled))
    (on arrow-right (do (numeric-key ArrowRight)) (when not-disabled))
    (on arrow-down (do (numeric-key ArrowDown)) (when not-disabled))
    (on arrow-left (do (numeric-key ArrowLeft)) (when not-disabled))
    (on shift-arrow-up (do (numeric-key ArrowUp shift)) (when not-disabled))
    (on shift-arrow-right (do (numeric-key ArrowRight shift)) (when not-disabled))
    (on shift-arrow-down (do (numeric-key ArrowDown shift)) (when not-disabled))
    (on shift-arrow-left (do (numeric-key ArrowLeft shift)) (when not-disabled))
    (on page-up (do (numeric-key PageUp)) (when not-disabled))
    (on page-down (do (numeric-key PageDown)) (when not-disabled))
    (on home (do (numeric-key Home)) (when not-disabled))
    (on end (do (numeric-key End)) (when not-disabled)))
  (state dragging
    (on drag (do move-to-pointer))
    (on release (target idle) (do move-to-pointer)))
  (part thumb
    (attr role slider)
    (attr aria-valuenow (context value))
    (attr aria-valuemin (context min))
    (attr aria-valuemax (context max))
    (attr aria-valuetext (context text))
    (attr aria-orientation (context orientation))
    (attr aria-disabled (context disabled))
    (attr data-state (state))
    (key ArrowUp arrow-up)
    (key ArrowRight arrow-right)
    (key ArrowDown arrow-down)
    (key ArrowLeft arrow-left)
    (key Shift+ArrowUp shift-arrow-up)
    (key Shift+ArrowRight shift-arrow-right)
    (key Shift+ArrowDown shift-arrow-down)
    (key Shift+ArrowLeft shift-arrow-left)
    (key PageUp page-up)
    (key PageDown page-down)
    (key Home home)
    (key End end))
  (part track
    (attr data-state (state))
    (on pointerdown grab)
    (on pointermove drag)
    (on pointerup release)
    (on lostpointercapture release)))
`,
  switch: `(switch-machine: machine
  (initial ready)
  (context (checked false) (disabled false))
  (state ready
    (on toggle (do (toggle checked)) (when not-disabled)))
  (part input
    (attr role switch)
    (attr aria-checked (context checked))
    (attr data-state (context checked))
    (key Enter toggle)
    (key Space toggle)
    (on press toggle)))
`,
  'text-area': `(text-area-machine: machine
  (initial idle)
  (context (disabled false) (readonly false) (invalid false))
  (state idle
    (on focus (target editing)))
  (state editing
    (on blur (target idle))
    (on commit (do read-value))
    (on revert (do restore-value) (when editable)))
  (part input
    (attr aria-invalid (context invalid))
    (attr data-state (state))
    (on focusin focus)
    (on focusout blur)
    (on change commit)
    (key Escape revert)))
`,
  'text-field': `(text-field-machine: machine
  (initial idle)
  (context (disabled false) (readonly false) (invalid false))
  (state idle
    (on focus (target editing)))
  (state editing
    (on blur (target idle))
    (on commit (do read-value))
    (on revert (do restore-value) (when editable)))
  (part input
    (attr aria-invalid (context invalid))
    (attr data-state (state))
    (on focusin focus)
    (on focusout blur)
    (on change commit)
    (key Escape revert)))
`,
});
